const API='https://statsapi.mlb.com/api/v1';
const names={108:'天使',109:'響尾蛇',110:'金鶯',111:'紅襪',112:'小熊',113:'紅人',114:'守護者',115:'洛磯',116:'老虎',117:'太空人',118:'皇家',119:'道奇',120:'國民',121:'大都會',133:'運動家',134:'海盜',135:'教士',136:'水手',137:'巨人',138:'紅雀',139:'光芒',140:'遊騎兵',141:'藍鳥',142:'雙城',143:'費城人',144:'勇士',145:'白襪',146:'馬林魚',147:'洋基',158:'釀酒人'};
const short={108:'LAA',109:'AZ',110:'BAL',111:'BOS',112:'CHC',113:'CIN',114:'CLE',115:'COL',116:'DET',117:'HOU',118:'KC',119:'LAD',120:'WSH',121:'NYM',133:'ATH',134:'PIT',135:'SD',136:'SEA',137:'SF',138:'STL',139:'TB',140:'TEX',141:'TOR',142:'MIN',143:'PHI',144:'ATL',145:'CWS',146:'MIA',147:'NYY',158:'MIL'};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function taipeiDay(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
export function shiftDay(day,n){return new Date(Date.parse(day+'T12:00:00Z')+n*86400000).toISOString().slice(0,10)}
export function recentGames(games,id,cutoff){return games.filter(g=>g.status.abstractGameState==='Final'&&Date.parse(g.gameDate)<cutoff&&[g.teams.home.team.id,g.teams.away.team.id].includes(id)).sort((a,b)=>Date.parse(b.gameDate)-Date.parse(a.gameDate)||b.gamePk-a.gamePk).slice(0,10)}
async function api(path,signal){const r=await fetch(API+path,{signal});if(!r.ok)throw new Error('MLB 資料暫時無法取得');return r.json()}
const flatten=d=>(d.dates||[]).flatMap(d=>d.games),time=d=>new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(d));
let controller,sequence=0,standingsLoaded=false,selectedLeague='103';
function historyMarkup(list,id){if(!list.length)return '<p class="muted">目前沒有已完賽紀錄</p>';return list.map(g=>{const home=g.teams.home.team.id===id,own=g.teams[home?'home':'away'],opp=g.teams[home?'away':'home'],won=own.isWinner===true;return `<div class="history-row"><span class="muted">${taipeiDay(new Date(g.gameDate)).slice(5).replace('-','/')}</span><span>${home?'vs':'@'} ${esc(names[opp.team.id]||opp.team.name)}</span><strong>${own.score}–${opp.score}</strong><span class="${won?'win-text':'loss-text'}">${won?'勝':own.score===opp.score?'和':'敗'}</span></div>`}).join('')}
function formMarkup(list,id){const wins=list.filter(g=>Object.values(g.teams).some(t=>t.team.id===id&&t.isWinner)).length,losses=list.length-wins;return `<details class="form"><summary><span class="muted">近 ${list.length} 場</span><strong class="record">${wins}-${losses}</strong><span class="history-link">比賽明細 ＋</span></summary><div class="history">${historyMarkup(list,id)}</div></details><div class="chips" aria-label="近況，由左至右為最近至最早">${list.map(g=>{const win=Object.values(g.teams).some(t=>t.team.id===id&&t.isWinner);return `<span class="chip ${win?'win':''}">${win?'W':'L'}</span>`}).join('')}</div>`}
function teamMarkup(side,role,key){const id=side.team.id,record=side.leagueRecord?`${side.leagueRecord.wins}–${side.leagueRecord.losses}`:'—';return `<div class="team"><div class="team-head"><span class="team-mark"><img src="https://www.mlbstatic.com/team-logos/${id}.svg" alt="${esc(names[id]||side.team.name)}隊徽" width="44" height="44" loading="lazy" onerror="this.hidden=true;this.parentElement.textContent='${short[id]||'MLB'}'"></span><div><div class="team-label">${role}</div><div class="team-name">${esc(names[id]||side.team.name)} <span class="season-record">${record}</span></div><div class="team-en">${esc(side.team.name)}</div></div></div><div id="form-${key}" class="form muted">近十場戰績讀取中…</div><div class="pitcher"><div class="pitcher-person">${side.probablePitcher?`<img class="headshot" src="https://img.mlbstatic.com/mlb-photos/image/upload/w_120,q_auto:best/v1/people/${side.probablePitcher.id}/headshot/67/current" alt="${esc(side.probablePitcher.fullName)}照片" width="54" height="68" loading="lazy" onerror="this.hidden=true">`:''}<div><div class="muted">預告先發</div><div class="pitcher-name">${esc(side.probablePitcher?.fullName||'待公布')}</div></div></div><div id="pitch-${key}" class="stats"><div><div class="muted">當季勝敗</div><div class="stat-value">—</div></div><div><div class="muted">ERA</div><div class="stat-value">—</div></div></div></div></div>`}
function gameCenter(g){if(g.status.abstractGameState!=='Final')return '<div class="versus">VS</div>';return `<div class="versus"><div class="final-score">${g.teams.away.score}–${g.teams.home.score}</div><div class="final-label">FINAL</div></div>`}
async function load(){if(!$('#date').value)return;controller?.abort();controller=new AbortController();const {signal}=controller,run=++sequence,day=$('#date').value;$('#status').textContent='正在取得 MLB 賽程…';$('#games').innerHTML='';$('#count').textContent='讀取中';$('#updated').textContent='尚未更新';$('#day-title').textContent=new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'long',day:'numeric',weekday:'long'}).format(new Date(day+'T12:00:00+08:00'));try{const data=await api(`/schedule?sportId=1&startDate=${shiftDay(day,-1)}&endDate=${day}&hydrate=probablePitcher`,signal);const games=flatten(data).filter(g=>taipeiDay(new Date(g.gameDate))===day).sort((a,b)=>Date.parse(a.gameDate)-Date.parse(b.gameDate));if(run!==sequence)return;$('#count').textContent=`${games.length} 場比賽`;$('#status').textContent='';if(!games.length){$('#games').innerHTML='<div class="empty">這一天沒有 MLB 賽程<br>可切換日期查看其他比賽。</div>';return}$('#games').innerHTML=games.map(g=>`<article class="game"><div class="game-top"><span><time>${time(g.gameDate)}</time> 開賽 · ${esc(g.venue.name)}</span><span>${esc(({Preview:'未開賽',Live:'進行中',Final:'已結束'})[g.status.abstractGameState]||g.status.detailedState)}${g.status.detailedState==='Postponed'?' · 延賽':''}</span></div><div class="match">${teamMarkup(g.teams.away,'AWAY / 客隊',g.gamePk+'-away')}${gameCenter(g)}${teamMarkup(g.teams.home,'HOME / 主隊',g.gamePk+'-home')}</div></article>`).join('');
const cutoff=Math.min(Date.now(),Date.parse(day+'T00:00:00+08:00')),ids=[...new Set(games.flatMap(g=>[g.teams.home.team.id,g.teams.away.team.id]))],recentPromise=api(`/schedule?sportId=1&teamId=${ids.join(',')}&startDate=${shiftDay(day,-120)}&endDate=${day}`,signal).then(flatten),pitchers=new Map();let partial=false;const jobs=games.flatMap(g=>['away','home'].map(async role=>{const side=g.teams[role],key=g.gamePk+'-'+role;try{const past=recentGames(await recentPromise,side.team.id,cutoff);if(run===sequence)$('#form-'+key).innerHTML=formMarkup(past,side.team.id)}catch(e){if(signal.aborted)return;partial=true;$('#form-'+key).textContent='近況暫時無法取得，請重新整理。'}if(!side.probablePitcher)return;const id=side.probablePitcher.id,season=g.season||day.slice(0,4),cacheKey=id+'-'+season;if(!pitchers.has(cacheKey))pitchers.set(cacheKey,api(`/people/${id}/stats?stats=season&group=pitching&season=${season}&gameType=R`,signal));try{const p=await pitchers.get(cacheKey),s=p.stats?.[0]?.splits?.find(x=>String(x.season)===String(season))?.stat;if(run===sequence)$('#pitch-'+key).innerHTML=`<div><div class="muted">${season} 勝敗</div><div class="stat-value">${s?esc(s.wins)+'-'+esc(s.losses):'—'}</div></div><div><div class="muted">ERA</div><div class="stat-value">${s?esc(s.era):'—'}</div></div>`}catch(e){if(signal.aborted)return;partial=true;$('#pitch-'+key).innerHTML='<span class="muted">投手數據暫時無法取得</span>'}}));await Promise.all(jobs);if(run!==sequence)return;if(partial)$('#status').textContent='部分數據未能載入，可按「更新資料」重試。';$('#updated').textContent='最後更新 '+time(new Date())+'（台灣）'}catch(e){if(signal.aborted||run!==sequence)return;$('#status').textContent='無法連線至 MLB 資料來源，請稍後按「更新資料」重試。';$('#count').textContent='尚無資料'}}
function standingRow(r){const split=t=>r.records?.splitRecords?.find(x=>x.type===t),home=split('home'),away=split('away'),last=split('lastTen'),id=r.team.id;return `<tr><td class="standing-team"><span class="standing-rank">${r.divisionRank}</span><img src="https://www.mlbstatic.com/team-logos/${id}.svg" alt="" width="28" height="28" loading="lazy">${esc(names[id]||r.team.name)}</td><td>${r.wins}</td><td>${r.losses}</td><td>${r.winningPercentage}</td><td>${r.gamesBack==='-'?'—':r.gamesBack}</td><td>${home?`${home.wins}-${home.losses}`:'—'}</td><td>${away?`${away.wins}-${away.losses}`:'—'}</td><td class="last-ten">${last?`${last.wins}-${last.losses}`:'—'}</td></tr>`}
function renderStandings(records){const divisions=records.filter(r=>String(r.league.id)===selectedLeague).sort((a,b)=>a.division.id-b.division.id);$('#standings').innerHTML=divisions.map(d=>`<article class="division"><div class="division-title">${esc(d.division.name.replace('American League ','AL ').replace('National League ','NL '))}</div><div class="table-scroll"><table class="standings-table"><thead><tr><th>球隊</th><th>勝</th><th>負</th><th>勝率</th><th>勝差</th><th>主場</th><th>客場</th><th>近 10 場</th></tr></thead><tbody>${[...d.teamRecords].sort((a,b)=>Number(a.divisionRank)-Number(b.divisionRank)).map(standingRow).join('')}</tbody></table></div></article>`).join('')}
async function loadStandings(force=false){if(standingsLoaded&&!force)return;$('#standings-status').textContent='正在取得最新大聯盟戰績…';$('#standings').innerHTML='';try{const data=await api(`/standings?leagueId=103,104&season=${taipeiDay().slice(0,4)}&standingsTypes=regularSeason&hydrate=team,division,league`);renderStandings(data.records||[]);standingsLoaded=true;$('#standings-status').textContent='';$('#updated').textContent='最後更新 '+time(new Date())+'（台灣）'}catch(e){$('#standings-status').textContent='無法連線至 MLB 資料來源，請稍後按「更新戰績」重試。'}}
function setView(view){const standings=view==='standings';$('#schedule-panel').hidden=standings;$('#standings-panel').hidden=!standings;$('#schedule-view').classList.toggle('selected',!standings);$('#standings-view').classList.toggle('selected',standings);$('#schedule-view').setAttribute('aria-pressed',String(!standings));$('#standings-view').setAttribute('aria-pressed',String(standings));if(standings)loadStandings()}
if(typeof document!=='undefined'){$('#date').value=shiftDay(taipeiDay(),1);$('#date').addEventListener('change',load);$('#prev').onclick=()=>{$('#date').value=shiftDay($('#date').value,-1);load()};$('#next').onclick=()=>{$('#date').value=shiftDay($('#date').value,1);load()};$('#tomorrow').onclick=()=>{$('#date').value=shiftDay(taipeiDay(),1);load()};$('#refresh').onclick=load;$('#schedule-view').onclick=()=>setView('schedule');$('#standings-view').onclick=()=>setView('standings');$('#standings-refresh').onclick=()=>loadStandings(true);$$('.league-tab').forEach(b=>b.onclick=()=>{selectedLeague=b.dataset.league;$$('.league-tab').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-selected',String(selected))});standingsLoaded=false;loadStandings()});load()}
const pitcherLogs=new Map();
function pitcherLogMarkup(splits){return `<div class="pitcher-log-scroll"><table class="pitcher-log-table"><thead><tr><th>日期</th><th>對手</th><th>局數</th><th>決定</th><th>失分</th><th>自責分</th><th>ERA</th><th>被安打</th><th>被全壘打</th></tr></thead><tbody>${[...splits].sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(x=>{const s=x.stat||{},decision=s.wins?'勝':s.losses?'敗':'—';return `<tr><td>${esc(String(x.date||'').slice(5).replace('-','/'))}</td><td>${x.isHome?'vs':'@'} ${esc(names[x.opponent?.id]||x.opponent?.name||'—')}</td><td>${esc(s.inningsPitched||'—')}</td><td>${decision}</td><td>${s.runs??'—'}</td><td>${s.earnedRuns??'—'}</td><td>${esc(s.era||'—')}</td><td>${s.hits??'—'}</td><td>${s.homeRuns??'—'}</td></tr>`}).join('')}</tbody></table></div>`}
async function showPitcherLog(person){const image=person.querySelector('.headshot'),id=image?.src.match(/people\/(\d+)\//)?.[1];if(!id)return;const host=person.closest('.pitcher');let detail=host.querySelector('.pitcher-log');if(detail){detail.open=!detail.open;return}detail=document.createElement('details');detail.className='pitcher-log pitcher-games';detail.open=true;detail.innerHTML='<summary>本季逐場投球明細</summary><div class="muted">正在取得資料…</div>';host.append(detail);try{const season=taipeiDay().slice(0,4);if(!pitcherLogs.has(id))pitcherLogs.set(id,api(`/people/${id}/stats?stats=gameLog&group=pitching&season=${season}&gameType=R&hydrate=opponent`));const data=await pitcherLogs.get(id),splits=data.stats?.[0]?.splits||[];detail.querySelector('div').outerHTML=splits.length?pitcherLogMarkup(splits):'<p class="muted">沒有本季例行賽逐場紀錄。</p>'}catch(e){detail.querySelector('div').textContent='逐場投球資料暫時無法取得，請稍後再試。'}}
if(typeof document!=='undefined'){document.addEventListener('click',e=>{const person=e.target.closest('.pitcher-person');if(person)showPitcherLog(person)});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest('.pitcher-person')){e.preventDefault();showPitcherLog(e.target.closest('.pitcher-person'))}})}
const seriesCache=new Map();let seriesRun=0;
function teamIdFromLogo(image){const match=image?.src.match(/team-logos\/(\d+)\.svg/);return match?.[1]}
async function loadSeasonSeries(){const run=++seriesRun,day=$('#date')?.value;if(!day)return;const cards=[...document.querySelectorAll('.game')];await Promise.all(cards.map(async card=>{if(card.dataset.seriesDay===day)return;card.dataset.seriesDay=day;const ids=[...card.querySelectorAll('.team-mark img')].map(teamIdFromLogo);const [awayId,homeId]=ids;if(!awayId||!homeId)return;const key=[awayId,homeId].sort().join('-')+'-'+day;if(!seriesCache.has(key))seriesCache.set(key,api(`/schedule?sportId=1&teamId=${awayId}&opponentId=${homeId}&startDate=${day.slice(0,4)}-03-01&endDate=${day}&gameType=R`).then(flatten));const slot=document.createElement('span');slot.className='season-series';slot.textContent='本季交手讀取中…';card.querySelector('.game-top')?.append(slot);try{const games=await seriesCache.get(key);if(run!==seriesRun)return;let wins=0,losses=0;games.filter(g=>g.status.abstractGameState==='Final').forEach(g=>{const own=g.teams.away.team.id===Number(awayId)?g.teams.away:g.teams.home;if(own.isWinner)wins++;else if(g.teams.away.score!==g.teams.home.score)losses++});slot.textContent=`本季交手：客隊 ${wins}–${losses} 主隊`}catch(e){if(run===seriesRun)slot.textContent='本季交手暫時無法取得'}}))}
if(typeof document!=='undefined'){new MutationObserver(()=>loadSeasonSeries()).observe($('#games'),{childList:true});}
